const config = $input.first().json;
const now = new Date();
const draftId = `ffs-${now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14)}`;

const topicBank = [
  'Why emergency funds matter before investing',
  'The difference between saving and investing',
  'How compound interest works in simple words',
  'Why budgeting is not about being cheap',
  'Common money mistakes beginners make',
  'What inflation means for everyday people',
  'How to avoid lifestyle inflation',
  'Good debt versus bad debt explained simply'
];

const topic = topicBank[Math.floor(Math.random() * topicBank.length)];
const prompt = `Create one YouTube Shorts draft for the channel ${config.channelName}. Topic: ${topic}. Audience: beginners. Tone: clear, simple, trustworthy. Length: about ${config.targetShortLengthSeconds} seconds. Include: hook, script, on-screen text beats, title, description, hashtags, and a short disclaimer that this is educational content and not personal financial advice. Return valid JSON with keys: topic, hook, script, onscreen_text, title, description, hashtags, disclaimer.`;

return [
  {
    json: {
      ...config,
      draftId,
      topic,
      prompt,
      createdAt: now.toISOString()
    }
  }
];

const base = $node['Build Prompt'].json;
const response = $input.first().json;

function safeParse(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return { rawText: String(value) };
  }
}

const body = safeParse(response.body ?? response.data ?? response);
const draft = body.draft ?? body.result ?? body.output ?? body;

const title = draft.title || `${base.topic} | Faceless Finance Shorts`;
const hook = draft.hook || `Most people misunderstand this money idea: ${base.topic}.`;
const script = draft.script || draft.rawText || `Hook: ${hook}\n\nSimple explanation: ${base.topic}.\n\nReminder: This is educational content, not personal financial advice.`;
const onscreenText = Array.isArray(draft.onscreen_text) ? draft.onscreen_text.join('\n') : (draft.onscreen_text || draft.onScreenText || 'Hook\nSimple explanation\nEducational disclaimer');
const hashtags = Array.isArray(draft.hashtags) ? draft.hashtags.join(' ') : (draft.hashtags || '#Finance #MoneyTips #PersonalFinance #Shorts');
const disclaimer = draft.disclaimer || 'Educational content only. Not personal financial advice.';
const description = draft.description || `${hook}\n\n${disclaimer}\n\n${hashtags}`;

const approveUrl = `${base.approvalBaseUrl}?draftId=${encodeURIComponent(base.draftId)}&action=approve`;
const rejectUrl = `${base.approvalBaseUrl}?draftId=${encodeURIComponent(base.draftId)}&action=reject`;

const approvalEmailHtml = `
<h2>Approval needed: ${title}</h2>
<p><strong>Draft ID:</strong> ${base.draftId}</p>
<p><strong>Topic:</strong> ${base.topic}</p>
<p><strong>Hook:</strong> ${hook}</p>
<h3>Script</h3>
<pre style="white-space:pre-wrap;font-family:Arial,sans-serif">${script}</pre>
<h3>Description</h3>
<pre style="white-space:pre-wrap;font-family:Arial,sans-serif">${description}</pre>
<p><a href="${approveUrl}">Approve draft</a> | <a href="${rejectUrl}">Reject draft</a></p>
<p>This workflow is draft + approval only. It does not auto-publish.</p>`;

return [
  {
    json: {
      ...base,
      status: 'Pending Approval',
      title,
      hook,
      script,
      onscreenText,
      description,
      hashtags,
      disclaimer,
      approveUrl,
      rejectUrl,
      approvalEmailHtml
    }
  }
];

const query = $input.first().json.query || {};
const draftId = query.draftId || 'unknown-draft';
const action = String(query.action || '').toLowerCase();
const status = action === 'approve' ? 'Approved' : action === 'reject' ? 'Rejected' : 'Needs Review';
const reviewedAt = new Date().toISOString();

return [
  {
    json: {
      draftId,
      action,
      status,
      reviewedAt,
      managerEmail: 'sajvindersingh8@gmail.com',
      message: `Draft ${draftId} marked as ${status}.`
    }
  }
];
